fn greater(a: Vec<i8>, b: Vec<i8>) -> Vec<bool> {
    // Ensure both input vectors have the same length
    assert_eq!(a.len(), b.len(), "Input vectors must have the same length");

    // Pre-allocate the result vector with the same length
    let mut result = Vec::with_capacity(a.len());

    // Compare each pair after converting to i32 and collect the boolean outcomes
    for (x, y) in a.iter().zip(b.iter()) {
        result.push(i32::from(*x) > i32::from(*y));
    }

    result
}

